def induced_inverse_2_3_2(n):
    low = 0
    high = n + 1
    while low < high:
        mid = (low + high) // 2
        if 2 * mid * mid + 3 * mid <= 2 * n:
            low = mid + 1
        else:
            high = mid
    return low - 1

